 are consistent, the answer is `2^(number of components)`. Otherwise it is 0. A union-find that tracks parity to the root handles both checks.

```python
import sys
def main():
    data=sys.stdin.buffer.read().split()
    t=int(data[0]); pos=1
    MOD=998244353
    out=[]
    for _ in range(t):
        H=int(data[pos]); W=int(data[pos+1]); pos+=2
        rows=data[pos:pos+H]; pos+=H
        ok=True
        for r in rows:
            if r.count(b'A')&1:
                ok=False;break
        if ok:
            colpar=[0]*W
            for r in rows:
                for j in range(W):
                    if r[j]==65: colpar[j]^=1
            for v in colpar:
                if v: ok=False;break
        if not ok:
            out.append(0);continue
        N=H+W
        parent=list(range(N))
        par=[0]*N
        size=[1]*N
        Qcur=[0]*W
        row0=[1 if c==65 else 0 for c in rows[0]]
        good=True
        for i in range(H):
            r=rows[i]
            Aflags=[1 if c==65 else 0 for c in r]
            if i==0:
                prevQ=row0
            else:
                prevQ=Qcur[:]
            Pprev=Aflags[0]
            P=0
            for j in range(W):
                if j>0:
                    Pprev=P
                    P^=Aflags[j]
                if not Aflags[j]:
                    c=1^Pprev^prevQ[j]
                    # union i and H+j with parity c
                    a=i
                    path=[]
                    while parent[a]!=a:
                        path.append(a); a=parent[a]
                    ra=a
                    if path:
                        acc=0
                        for v in reversed(path):
                            acc^=par[v]; par[v]=acc; parent[v]=ra
                        pa=par[i]
                    else:
                        pa=0
                    b=H+j
                    path=[]
                    while parent[b]!=b:
                        path.append(b); b=parent[b]
                    rb=b
                    if path:
                        acc=0
                        for v in reversed(path):
                            acc^=par[v]; par[v]=acc; parent[v]=rb
                        pb=par[H+j]
                    else:
                        pb=0
                    if ra==rb:
                        if pa^pb!=c:
                            good=False;break
                    else:
                        if size[ra]>size[rb]:
                            ra,rb=rb,ra
                        parent[ra]=rb
                        par[ra]=pa^pb^c
                        size[rb]+=size[ra]
            if not good:
                break
            if i>0:
                for j in range(W):
                    if Aflags[j]: Qcur[j]^=1
        if not good:
            out.append(0);continue
        comps=0
        for v in range(N):
            if parent[v]==v: comps+=1
        out.append(pow(2,comps,MOD))
    sys.stdout.write("\n".join(map(str,out))+"\n")
main()
